  const mine = power.find((r) => r.team === ME); if (!mine) return { worst: [], list: [] };
  const needs = POS_LIST.filter((g) => g !== "K" && g !== "DEF").map((g) => ({ pos: g, mine: posStrength(mine, g), gap: posStrength(mine, g) - avg[g] })).sort((a, b) => a.gap - b.gap);
