function tierOf(e) { if (e.ev == null || e.ev <= 0.005) return e.fair != null && e.pWin - e.fair > 0.01 ? "Watch" : null; if (e.ev >= 0.06 && e.nb >= 2 && e.p.pwF != null && e.p.pwP != null) return "Strong"; if (e.ev >= 0.03 && e.nb >= 1) return "Good"; return "Lean"; }
